+      margin: 0 0 1.75rem;
+      color: var(--muted);
+    }
+
+    .form-field {
+      padding: 1rem;
+      border: 1px solid rgba(185, 194, 216, 0.18);
+      border-radius: 0.9rem;
+      background: var(--panel-strong);
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 0.75rem;
+    }
+
+    input[type="checkbox"] {
+      width: 1.25rem;
