+      margin: 0.15rem 0 0;
+      accent-color: var(--accent-strong);
+      cursor: pointer;
+    }
+
+    input[type="checkbox"]:focus-visible,
+    button:focus-visible,
+    a:focus-visible {
+      outline: 3px solid var(--ring);
+      outline-offset: 3px;
+    }
+
+    label {
+      font-weight: 700;
+      cursor: pointer;
+    }
+
+    .required {
+      color: var(--accent);
+      font-weight: 800;
+    }
+
+    .helper,
+    .error,
+    .status {
+      margin: 0.55rem 0 0 2rem;
+      font-size: 0.95rem;
+    }
+
