    .card {
      padding: clamp(1.5rem, 5vw, 2.25rem);
      border: 1px solid rgba(185, 194, 216, 0.16);
      border-radius: 1.25rem;
      background: rgba(21, 27, 46, 0.92);
      box-shadow: 0 1.5rem 4rem var(--shadow);
      backdrop-filter: blur(16px);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.75rem, 6vw, 2.3rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 1.75rem;
      color: var(--muted);
    }

    .form-field {
      padding: 1rem;
      border: 1px solid rgba(185, 194, 216, 0.18);
      border-radius: 0.9rem;
      background: var(--panel-strong);
    }

    .checkbox-row {
      display: flex;
      align-items: flex-start;
      gap: 0.75rem;
    }

    input[type="checkbox"] {
      width: 1.25rem;
      height: 1.25rem;
      flex: 0 0 auto;
      margin: 0.15rem 0 0;
      accent-color: var(--accent-strong);
      cursor: pointer;
    }

    input[type="checkbox"]:focus-visible,
    button:focus-visible,
    a:focus-visible {
      outline: 3px solid var(--ring);
      outline-offset: 3px;
    }

    label {
      font-weight: 700;
      cursor: pointer;
    }

    .required {
      color: var(--accent);
      font-weight: 800;
    }

    .helper,
    .error,
    .status {
      margin: 0.55rem 0 0 2rem;
      font-size: 0.95rem;
    }

    .helper {
      color: var(--muted);
    }

    .error {
      color: var(--error);
      font-weight: 700;
    }

    .error[hidden] {
      display: none;
    }

    a {
      color: var(--accent);
      text-underline-offset: 0.18em;
    }

    a:hover {
      color: #bae6fd;
    }

    button {
      width: 100%;
      min-height: 3rem;
      margin-top: 1.25rem;
      border: 0;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      color: #06111f;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 0.75rem 1.5rem rgba(56, 189, 248, 0.2);
    }

    button:hover {
      filter: brightness(1.06);
    }

    .status {
      min-height: 1.5rem;
      color: #bbf7d0;
      font-weight: 700;
      text-align: center;
    }

    @media (forced-colors: active) {
      .card,
      .form-field,
      button {
        border: 1px solid CanvasText;
        box-shadow: none;
      }

      button {
        color: ButtonText;
        background: ButtonFace;
      }
    }
  </style>
</head>
<body>
  <main>
    <section class="card" aria-labelledby="form-title">
      <h1 id="form-title">Review terms</h1>
      <p class="intro">Confirm your consent before continuing.</p>

      <form id="consent-form" novalidate>
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="agree-terms"
              name="agreeTerms"
              type="checkbox"
              required
              aria-describedby="terms-helper terms-error"
            >
            <label for="agree-terms">
              I agree to the <a href="#">terms of use</a>
              <span class="required">(required)</span>
            </label>
          </div>
          <p id="terms-helper" class="helper">Required to create or continue using your account.</p>
          <p id="terms-error" class="error" hidden>Error: You must agree to the terms of use before submitting.</p>
        </div>

        <button type="submit">Continue</button>
        <p id="form-status" class="status" role="status"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#consent-form");
    const checkbox = document.querySelector("#agree-terms");
    const error = document.querySelector("#terms-error");
    const status = document.querySelector("#form-status");

    function setConsentError(isInvalid) {
      checkbox.setAttribute("aria-invalid", String(isInvalid));
      error.hidden = !isInvalid;
    }

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      status.textContent = "";

      if (!checkbox.checked) {
        setConsentError(true);
        checkbox.focus();
        return;
      }

      setConsentError(false);
      status.textContent = "Thanks. Your consent has been recorded.";
      form.reset();
    });

    checkbox.addEventListener("change", () => {
      if (checkbox.checked) {
        setConsentError(false);
      }
    });
  </script>
</body>
</html>
