       box-shadow: 0 0.75rem 1.5rem rgba(56, 189, 248, 0.2);
     }

     button:hover {
       filter: brightness(1.06);
     }

     .status {
       min-height: 1.5rem;
       color: #bbf7d0;
       font-weight: 700;
       text-align: center;
     }

     @media (forced-colors: active) {
       .card,
       .form-field,
       button {
         border: 1px solid CanvasText;
         box-shadow: none;
       }

       button {
         color: ButtonText;
         background: ButtonFace;
       }
     }
   </style>
 </head>
 <body>
   <main>
     <section class="card" aria-labelledby="form-title">
       <h1 id="form-title">Review terms</h1>
       <p class="intro">Confirm your consent before continuing.</p>

       <form id="consent-form" novalidate>
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="agree-terms"
               name="agreeTerms"
               type="checkbox"
               required
               aria-describedby="terms-helper terms-error"
             >
             <label for="agree-terms">
               I agree to the terms of use
               <span class="required" aria-hidden="true">*</span>
               <span class="required-text">required</span>
             </label>
           </div>
           <p id="terms-helper" class="helper">Required to create or continue using your account.</p>
           <p id="terms-error" class="error" hidden>Error: You must agree to the terms of use before submitting.</p>
         </div>

         <button type="submit">Continue</button>
         <p id="form-status" class="status" role="status"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#consent-form");
     const checkbox = document.querySelector("#agree-terms");
     const error = document.querySelector("#terms-error");
     const status = document.querySelector("#form-status");

     function setConsentError(isInvalid) {
       checkbox.setAttribute("aria-invalid", String(isInvalid));
       error.hidden = !isInvalid;
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       status.textContent = "";

       if (!checkbox.checked) {
         setConsentError(true);
         checkbox.focus();
         return;
       }

       setConsentError(false);
       status.textContent = "Thanks. Your consent has been recorded.";
       form.reset();
     });

     checkbox.addEventListener("change", () => {
       if (checkbox.checked) {
         setConsentError(false);
       }
     });
   </script>
 </body>
 </html>

